import json, subprocess
root = "/home/ross-geller/Projects/minastik/swiss-keepsakes"
review = "docs/ux/prototype/screens/phase1-review/phase1-review-2026-10-13.json"
pre = (f"Swiss Keepsakes prototype, owner review follow-up. Repo root: {root} (no git). FIRST read {root}/docs/ux/prototype/worker-brief.md and follow it exactly, "
       "including the 'Design skills' section. The owner's verdicts are in " + review + "; the current screenshots of your screen are in "
       "docs/ux/prototype/screens/phase1-review/img/ (manifest-*.json says which). Read the original step report too.\n")
def ack(port, step, extra=""):
    return (f"\nObservable acceptance: before/after screenshots at 375px EN and DE (merchant/partner also 1024px) in docs/ux/prototype/screens/{step}/, every state of the original step still reachable, "
            f"tsc on the whole tree and eslint on your files clean.{extra} Dev server port {port}. Report: docs/ux/prototype/reports/{step}.md, including how you used the skill (commands, key decisions).")
T = [
 ("I0","I0 impeccable init: PRODUCT.md",[],None,
  "Target: PRODUCT.md at the repo root (impeccable's product-truth file). Change: invoke the impeccable skill and run its init flow (`init` command) for this project. Answer its questions yourself from docs/PRD/Swiss_keepsakes_PRD.md, docs/ux/ux-spec-phase1.md, docs/ux/prototype/flow-1-outline.md, docs/ux/decisions.tsv and the existing .impeccable/surfaces/*.md. Ask the coordinator through the preamble's ask command only for facts that none of those answer. Record the product: Swiss Keepsakes, Lucerne gifts and tours; guests are international travellers on phones (EN/DE); merchant staff (Owner, Manager) and referral partners use back-office views. Record the guest-app direction already accepted (Airbnb/Klook-like native app frame, decisions.tsv) and the existing token and theme authority. Do not create DESIGN.md unless init requires it, and do not change product code. If init offers to install hooks or a live mode, decline. Acceptance: PRODUCT.md exists and reads correctly; report docs/ux/prototype/reports/I0.md lists each init question and the source of its answer."),
 ("1.11r","1.11r M04 merchant order detail redesign (evon)",[],5211,
  "Skill: evon:ui-ux (dashboard). Owner verdict on 1.11: 'need redesign on the entire flow, current layout look flat and boring'. Target: M04 at /store/orders/$orderId: features/merchant/order-detail/** (decision block, sheets, sections) and its route. Change: redesign the whole M04 flow: request decision (accept with stock per line + confirmation sheet, change date/place with required note, decline with reason + ConfirmDialog), items, guest, source, payments, commission, log, policy. Give it a real back-office layout (clear header with status and key facts, primary action area, structured sections or tabs), 375px first plus a two-column layout from 1024px. Keep the FulfilmentActions slot working (task 1.15r restyles it after you, in your style; document the style tokens and patterns you set in the report for it). Keep all T0 transitions and behaviour. Ownership: features/merchant/order-detail/** except components/fulfilment-actions.tsx, routes/store/orders/$orderId.tsx, i18n 'merchantOrder.' keys."),
 ("1.9r","1.9r M02 Today as widgets (evon)",[],5212,
  "Skill: evon:ui-ux (dashboard). Owner verdict on 1.9: 'the UI is too simple and boring, pls turn it into widgets, search internet for inspirations on how a proper overview dashboard should look like'. Use WebSearch for overview-dashboard references (merchant or host dashboards such as Shopify admin home, Airbnb host Today, Stripe dashboard home) and list what you took from each in the report. Target: features/merchant/today/** and routes/store/index.tsx. Change: M02 becomes a widget dashboard: task widgets with counts and links to /store/orders?status=…, money widgets (still to collect, commission to pay, completed this week) with small trends or breakdowns where the data allows, plus a 'next pickups' widget (upcoming ready and preparing orders by date) if it helps; 375px stacked, from 1024px a grid. All numbers from T0 selectors; keep the empty state. Ownership: those files, i18n 'merchantToday.' keys."),
 ("1.17r","1.17r P02 partner report with widgets and charts (evon)",[],5213,
  "Skill: evon:ui-ux (analytics). Owner verdict on 1.17: 'ui too flat and boring, redesign entirely, use widget and charts for better visual'. Also read the dataviz skill before writing chart code. Target: routes/partner.tsx, features/partners/report/**. Change: P02 becomes an analytics view: period control (day/week/month), KPI widgets (commission after adjustments, actually paid, still to pay, plus orders count), a chart of commission over the period (estimated vs recorded), product-group breakdown as a chart, then the transaction list. Keep the AC12 privacy rule: only this partner's rows; no email, phone, engraving or pickup details. Use inline SVG or a small charting approach that works with the project's stack (no new heavy dependency without saying why in the report). Ownership: those files, i18n 'partnerReport.' keys."),
 ("1.15r","1.15r M04 fulfilment + M08 in M04's new style (evon)",["1.11r"],5214,
  "Skill: evon:ui-ux (dashboard). Owner verdict on 1.15: 'redesign the ui entirely, should be the same style with the page from M04'. Read reports/1.11r.md first for M04's new style. Target: features/merchant/order-detail/components/fulfilment-actions.tsx and features/merchant/record-payment/**. Change: redesign the fulfilment actions (Ready, Handed over, Complete locked with reason, combined button) and the M08 Record payment sheet (amount, method, time, note, consequence on the button, duplicate warning, above-balance block) to match the new M04. Ownership: those files, i18n 'fulfilment.' and 'recordPayment.' keys."),
 ("1.6r","1.6r Sign-in screen (impeccable)",["I0"],5215,
  "Skill: impeccable (non-dashboard). Owner verdict on 1.6 (part 1): 'design a proper auth screen with 2 column layout, left side is the sign in form (no need for sign up or forgot password as we only do either google login or otp), the left is a hero image, search internet for a lucerne related image'. Read it as: form on one side, Lucerne hero image on the other. Change: replace the C05 sign-in sheet with a sign-in screen (route e.g. /sign-in with a return-to search param). Two columns from 1024px (form + hero image). On phones inside the 430px guest frame, put the hero on top or as the background, with the form below; explain the choice. Google (simulated) and email, then a 6-digit code: keep every state (wrong 000000, expired, resend in 30 s, 5-attempt lock, N01 mail). Update useRequireSignIn so cart Continue and Account go to the screen and come back to where they were (C06 after Continue). Image: WebSearch for a Lucerne photo with a licence that allows use (Unsplash, Pexels or Wikimedia Commons). Download it to front-end/src/assets/photos/ and add its credit to CREDITS.txt in the same format. Ownership: features/auth/**, the new route, i18n 'auth.' keys, assets and CREDITS.txt. Don't touch the Account page (1.12r owns it)."),
 ("1.12r","1.12r Account hub (impeccable)",["I0"],5216,
  "Skill: impeccable (non-dashboard). Owner verdicts on 1.6 (part 2) and 1.12: 'redesign the account screen properly, it supposed to let users manage their bookings/orders/payment info/profile, not just transactions history'. Target: routes/_guest/account.tsx, features/transactions/** (list) and a new features/account/**. Change: the Account tab becomes an account hub with a profile header (name, email, sign out), sections for Orders (gift orders, the current C14 list with both labels, linking to C15), Bookings (tours; Phase 2: an honest empty state with 'Tours come later'), Payment info (simulated: payments made from order payment history, plus saved methods as a clear 'not in the prototype' placeholder, since the PRD stores no cards; check the PRD and say what you show), Profile (name, email, language, trip profile answers from C07 if present, editable in the demo store), and Mail/notifications if useful. The signed-out state links to the sign-in screen (1.6r is building it in parallel; until it lands, keep calling useRequireSignIn). Use tabs or sections, whichever impeccable recommends for a phone. Ownership: those files, i18n 'account.' and 'transactions.' keys."),
 ("1.13r","1.13r C15 guest order detail with tabs (impeccable)",["I0"],5217,
  "Skill: impeccable (non-dashboard). Owner verdict on 1.13: 'redesign the ui entirely, we should use tab-layout for better content focus instead of a long scrolling page. additionally, the ui is terrible'. Target: routes/_guest/account_.orders.$orderId.tsx, features/transactions/order-detail/**. Change: C15 gets a header with what matters now (status, both labels, the one next action: pay with deadline, cancel, request again, write review) and tabs, e.g. Overview (pickup date and place, gifts, amounts), Payments (history, due amounts), Timeline (log), Policy (policy at time of order, contact shop with copyable reference). Keep every state from report 1.13 (payment due with auto-cancel warning, changed place note, preparing, ready, handed over with balance, completed with review, declined, cancelled overdue with request again, payment processing, received after cancellation), the Pay link to C12, the ConfirmDialog cancel and the review sheet (features/reviews, read-only for you). Ownership: those files, i18n 'guestOrder.' keys."),
 ("1.8r","1.8r C07 Request sent, consistent with C06 (impeccable)",["I0"],5218,
  "Skill: impeccable (non-dashboard). Owner verdict on 1.8: 'reuse the component on the Review and send screen on this page; redesign other sections on the page to ensure consistency'. Target: routes/_guest/cart_.sent.tsx, features/checkout/components/request-sent.tsx, trip-profile.tsx and their hooks. Change: C07 lists the sent orders with the same order/gift-slip components C06 uses (review-view.tsx). If they are inline in review-view.tsx, extract them into features/checkout/components/ as shared components with no visual change to C06, and verify C06 before and after with screenshots. Then redesign 'what happens next' and the trip profile to match. Note: the owner's other session may have edited C06 recently; re-read review-view.tsx right before extracting. Ownership: C07 files, the extraction from review-view.tsx (no visual change), i18n 'requestSent.' and 'tripProfile.' keys."),
]
ids = {}
for key,title,deps,port,body in T:
    spec = pre + body + (ack(port,key) if port else "")
    r = subprocess.run(["orca","orchestration","task-create","--spec",spec,"--task-title",title,"--display-name",title,"--deps",json.dumps([ids[d] for d in deps]),"--json"],capture_output=True,text=True)
    t = json.loads(r.stdout)["result"]; t = t.get("task",t); ids[key] = t["id"]; print(key, t["id"])
json.dump(ids, open(f"{root}/docs/ux/prototype/redesign-task-ids.json","w"), indent=1)
